"""python -m wfm run --client <name> --week <YYYY-Www>"""
from __future__ import annotations

import argparse
import json
import sys
from datetime import date
from pathlib import Path

from wfm import board, registry, weeks
from wfm.config import OUT_DIR, load_config
from wfm.evaluate.metrics import evaluate
from wfm.export import LAYOUTS, export_schedule
from wfm.export.base import check_week, read_schedule
from wfm.ingest.loader import load_week
from wfm.notify import notify_dir, write_notifications
from wfm.report import compare, history, summary, volume
from wfm.report import markdown as md
from wfm.roster import load_agents
from wfm.scheduler.greedy import schedule_week, to_frame
from wfm.staffing.required import add_required


def run(client: str, week: str) -> dict:
    cfg = load_config(client)
    demand = load_week(cfg, week)
    req = add_required(demand, cfg)
    agents = load_agents(client)
    if cfg.get("scheduler", "greedy") == "v2":   # WFM-231, per client
        from wfm.scheduler.greedy_v2 import schedule_week as schedule_v2
        shifts = schedule_v2(req, cfg, agents, week)
    else:
        shifts = schedule_week(req, cfg, agents, week)
    sched = to_frame(shifts)

    out = OUT_DIR / client
    out.mkdir(parents=True, exist_ok=True)
    sched.to_csv(out / "schedule.csv", index=False)
    result = evaluate(req, sched, cfg, agents, week)
    (out / "eval.json").write_text(json.dumps(result, indent=2) + "\n")
    if cfg.get("runbook"):   # the client's contract asks for a weekly reconciliation report
        from wfm.report import runbook
        runbook.write(out, result, cfg)
    return result


# The subcommands below are off the run path: they read the registry, the data files, or what `run`
# wrote to out/. Each returns an exit code.

def _week(s: str) -> str:
    try:
        weeks.parse(s)
    except ValueError as e:
        raise argparse.ArgumentTypeError(str(e)) from None
    return s


def _date(s: str) -> date:
    try:
        return date.fromisoformat(s)
    except ValueError:
        raise argparse.ArgumentTypeError(f"not a date: {s!r} (expected YYYY-MM-DD)") from None


def _out(args) -> Path:
    return Path(args.out) if getattr(args, "out", None) else OUT_DIR


def _in_range(week: str, first: str | None, last: str | None) -> bool:
    return not ((first and weeks.key(week) < weeks.key(first)) or (last and weeks.key(week) > weeks.key(last)))


def _write_report(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text)
    print(text, end="")
    print(f"wrote {path}", file=sys.stderr)


def _run_outputs(client: str, week: str, out: Path):
    """Config, eval.json and schedule segments of the last run, checked to be this client-week's."""
    cfg = load_config(client)
    ev = history.read_eval(out / client / "eval.json")
    history.check_eval(ev, client, week, out / client / "eval.json")
    segments = read_schedule(out / client / "schedule.csv")
    check_week(segments, week, cfg["tz"])
    return cfg, ev, segments


def clients_cmd(args) -> int:
    reg = registry.load_registry()
    recs = list(reg.values()) if args.status is None else registry.by_status(reg, args.status)
    if args.active_on:
        recs = [r for r in registry.active_on(reg, args.active_on) if r in recs]
    if args.board:
        out = _out(args)
        if args.week:
            _write_report(out / "reports" / f"board_{args.week}.md",
                          board.render(board.board(recs, args.week, out), args.week))
        elif args.first and args.last:
            _write_report(out / "reports" / f"board_{args.first}_{args.last}.md",
                          board.grid(recs, args.first, args.last, out))
        else:
            raise SystemExit("--board needs --week, or --from and --to")
        return 0
    if args.timeline:
        print(registry.timeline(recs, args.until or date.today()))
        return 0
    if args.check:
        problems = [p for r in recs for p in registry.check(r, layouts=LAYOUTS, data=args.data)]
        for p in problems:
            print(p)
        n = {lvl: sum(p.level == lvl for p in problems) for lvl in (registry.ERROR, registry.WARNING, registry.PENDING)}
        print(f"{len(recs)} client(s) checked: {n['error']} error(s), {n['warning']} warning(s), {n['pending']} pending")
        return 1 if n["error"] else 0
    if args.markdown:
        print(registry.render_markdown(recs))
        return 0
    today = date.today()
    rows = [[r.key, r.status, *registry.period(r), len(r.weeks_served(today)) or md.DASH, f"{r.grain} min", r.tz,
             r.export_layout or md.DASH] for r in recs]
    print(md.text_table(["client", "status", "from", "to", "weeks", "grain", "tz", "export"], rows,
                        align="llllrrll", indent=0))
    return 0


def volume_cmd(args) -> int:
    cfg = load_config(args.client)
    rows = volume.volume_report(cfg, args.first, args.last, min_run=args.min_run)
    print(volume.render(cfg, rows, days=args.days, shape=args.profile), end="")
    if args.csv and rows:
        path = _out(args) / args.client / "reports" / f"volume_{args.first or rows[0].week}_{args.last or rows[-1].week}.csv"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(volume.to_csv(rows))
        print(f"wrote {path}", file=sys.stderr)
    return 0


def archive_cmd(args) -> int:
    a = history.archive(args.client, args.week, _out(args))
"""Week-aware scheduler (WFM-231), selected per client with `scheduler: v2` in its config.

`greedy.py` places one local day at a time and audits the contract rules afterwards. This scheduler
keeps week state per agent and enforces the rules while placing:

  * rest: `min_rest_hours` of elapsed time between one shift's end and the same agent's next start,
    checked on both sides of a candidate day (the repair pass can add a shift before an existing one);
  * split templates only for the contracts in `split_shift_contracts`;
  * weekly-hour caps in elapsed hours, the consecutive-day limit, one template per local day;
  * minimum cover per queue (`min_cover`) and per-queue operating hours (`queue_hours`).

Breaks follow `break_placement: surplus` (SOW 2.3): one break per shift of `min_shift_hours` or more,
starting 2-5 h after the shift starts, in the planning interval where the queue's gross coverage
surplus (agents scheduled on the queue, ignoring breaks, minus agents required) is largest. Because
every break in a window lands on the same few intervals, the plan is then repaired: while operating
intervals are short *net of breaks*, the shift that cuts the shortfall most is added, within the
hour budget (`efficiency_bound` x required hours). Deterministic: fixed template order, fixed
tie-breaks (ADR 0003).
"""
from __future__ import annotations

import math
import random
from collections import defaultdict
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

import pandas as pd

from wfm import constraints
from wfm.ingest.loader import local_days
from wfm.roster import Agent
from wfm.scheduler.greedy import Shift, _covered, place_breaks as _place_breaks_midpoint
from wfm.scheduler.templates import Template, templates_for

DEFAULT_MIN_REST_HOURS = 11.0


def _elapsed_hours(segments) -> float:
    return sum((e - s).total_seconds() for s, e in segments) / 3600.0


def operating_slots(queue: str, grid, cfg: dict) -> list[datetime]:
    """Planning intervals in which `queue` operates (client hours, narrowed by `queue_hours`)."""
    lo, hi = (cfg.get("queue_hours") or {}).get(queue, cfg["operating_hours"])
    z = ZoneInfo(cfg["tz"])
    out = []
    for t in grid:
        loc = t.astimezone(z)
        if lo <= loc.hour + loc.minute / 60 < hi:
            out.append(t)
    return out


class _Plan:
    """Shifts placed so far, with the week state needed to test a candidate."""

    def __init__(self, req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str):
        self.cfg, self.agents, self.week = cfg, agents, week
        self.tz = cfg["tz"]
        self.z = ZoneInfo(self.tz)
        self.queues = list(dict.fromkeys(req["queue"]))
        self.grid = sorted(set(req["interval_start_utc"]))
        self.step = timedelta(minutes=cfg["interval_minutes"])
        self.required = {q: dict(zip(g["interval_start_utc"], g["required"])) for q, g in req.groupby("queue")}
        self.floors = {q: {t: constraints.floor(q, t, cfg) for t in self.grid} for q in self.queues}
        self.templates = templates_for(cfg)
        self.min_rest = timedelta(hours=float(cfg.get("min_rest_hours", DEFAULT_MIN_REST_HOURS)))
        self.split_ok = set(cfg.get("split_shift_contracts") or ["FT", "PT"])
        self.days = local_days(week, self.tz)
        self.day_grid = {d: [t for t in self.grid if t.astimezone(self.z).date() == d] for d in self.days}
        self.ops = {q: operating_slots(q, self.grid, cfg) for q in self.queues}
        self.shifts: list[Shift] = []
        self.by_agent: dict[str, list[Shift]] = defaultdict(list)
        self.cover = {q: defaultdict(int) for q in self.queues}
        self.cross = {q: defaultdict(int) for q in self.queues}
        self.skills = {a.agent_id: a.skills for a in agents}
        self.agent = {a.agent_id: a for a in agents}
        self._scores: dict[tuple[date, str], tuple] = {}
        self.dq: dict[tuple[date, str], list[Shift]] = defaultdict(list)   # shifts per (local day, queue)
        self.op_set = {q: set(self.ops[q]) for q in self.queues}

    # -- placement -----------------------------------------------------------------------------
    def feasible(self, a: Agent, tpl: Template, day: date, segs) -> bool:
        if tpl.is_split and a.contract not in self.split_ok:
            return False
        mine = self.by_agent[a.agent_id]
        if any(s.day == day for s in mine):
            return False
        if _elapsed_hours(s for sh in mine for s in sh.segments) + _elapsed_hours(segs) > self.cfg["weekly_hours"][a.contract] + 1e-9:
            return False
        worked = {s.day for s in mine} | {day}
        run, d = 1, day - timedelta(days=1)
        while d in worked:
            run, d = run + 1, d - timedelta(days=1)
        d = day + timedelta(days=1)
        while d in worked:
            run, d = run + 1, d + timedelta(days=1)
        if run > self.cfg["max_consecutive_days"]:
            return False
        start, end = segs[0][0], segs[-1][1]
        for s in mine:
            s_start, s_end = s.segments[0][0], s.segments[-1][1]
            if s_end <= start:
                if start - s_end < self.min_rest:
                    return False
            elif end <= s_start:
                if s_start - end < self.min_rest:
                    return False
            else:
                return False
        return True

    def pick_agent(self, q: str, tpl: Template, day: date, segs) -> Agent | None:
        """Specialists first (they cannot be used elsewhere), then the fewest hours, then id."""
        hours = {a.agent_id: _elapsed_hours(s for sh in self.by_agent[a.agent_id] for s in sh.segments)
                 for a in self.agents}
        cands = [a for a in self.agents if q in a.skills and self.feasible(a, tpl, day, segs)]
        if not cands:
            return None
        return min(cands, key=lambda a: (len(a.skills & set(self.queues)), hours[a.agent_id], a.agent_id))

    def add(self, a: Agent, q: str, tpl: Template, day: date, segs, ivs) -> Shift:
        return self.insert(Shift(a.agent_id, q, tpl, day, segs, ivs))

    def insert(self, sh: Shift) -> Shift:
        self.shifts.append(sh)
        self.by_agent[sh.agent_id].append(sh)
        self.dq[(sh.day, sh.queue)].append(sh)
        self._touch(sh)
        for t in sh.intervals:
            self.cover[sh.queue][t] += 1
            for other in self.skills[sh.agent_id] & set(self.queues) - {sh.queue}:
                self.cross[other][t] += 1
        return sh

    def remove(self, sh: Shift) -> None:
        self.shifts.remove(sh)
        self.by_agent[sh.agent_id].remove(sh)
        self.dq[(sh.day, sh.queue)].remove(sh)
        self._touch(sh)
        for t in sh.intervals:
            self.cover[sh.queue][t] -= 1
            for other in self.skills[sh.agent_id] & set(self.queues) - {sh.queue}:
                self.cross[other][t] -= 1

    def _touch(self, sh: Shift) -> None:
        for q in self.queues:
            self._scores.pop((sh.day, q), None)

    def fill_day(self, day: date) -> None:
        """Greedy template placement for one local day against requirement and floors, gross."""
        dead: set[tuple[str, str]] = set()
        day_grid = self.day_grid[day]
        pen = float(self.cfg.get("overcover_penalty", 1.0))
        while True:
            best, best_val = None, 0.0
            for tpl in self.templates:
                segs = tpl.segments_utc(day, self.tz)
                ivs = _covered(segs, day_grid)
                for q in self.queues:
                    if (tpl.id, q) in dead:
                        continue
                    # +1 for each interval the shift helps, -penalty for each it only over-covers
                    val = sum(min(1, u) if u > 0 else -pen
                              for u in (constraints.uncovered(self.required[q][t], self.floors[q][t], self.cover[q][t],
                                                              self.cross[q][t], self.cfg) for t in ivs))
                    if val > best_val + 1e-9:
                        best, best_val = (tpl, q, segs, ivs), val
            if best is None or best_val * (self.step.total_seconds() / 3600) < 0.5:
                return
            tpl, q, segs, ivs = best
            a = self.pick_agent(q, tpl, day, segs)
            if a is None:
                dead.add((tpl.id, q))
                continue
            self.add(a, q, tpl, day, segs, ivs)

    # -- breaks and scoring ----------------------------------------------------------------------
    def _window(self, sh: Shift) -> list[tuple[datetime, bool]]:
        """Intervals where `sh` may take its break (SOW 2.3: starts 2-5 h after the shift starts and the
        break fits inside a segment), each flagged True if it is off the window edge."""
        w = getattr(sh, "_window", None)
        if w is None:
            rule = self.cfg["break"]
            length = timedelta(minutes=rule["minutes"])
            lo, hi = (timedelta(hours=h) for h in rule["window_hours"])
            start = sh.segments[0][0]
            w = [(t, lo < t - start < hi) for t in sh.intervals
                 if lo <= t - start <= hi and any(s <= t and t + length <= e for s, e in sh.segments)]
            sh._window = w
        return w

    def breaks(self, day: date, q: str) -> dict[datetime, int]:
        """SOW 2.3 for the shifts of one queue on one local day: each long shift takes its break in
        the window interval with the largest gross surplus (agents on the queue, ignoring breaks,
        minus agents required). Returns agents on break per interval."""
        rule = self.cfg["break"]
        taken: dict[datetime, int] = defaultdict(int)
        req, cov = self.required[q], self.cover[q]
        group = self.dq[(day, q)]
        for sh in group:
            sh.break_start, sh.break_minutes = None, 0
        for sh in sorted(group, key=lambda s: (s.segments[0][0], s.agent_id)):
            if sh.hours < rule["min_shift_hours"] - 1e-9:
                continue
            closed = self._window(sh)
            if not closed:
                continue
            surplus = {t: cov[t] - req[t] for t, _ in closed}
            top = max(surplus.values())
            tied = [(t, inner) for t, inner in closed if surplus[t] == top]
            pool = [t for t, inner in tied if inner] or [t for t, _ in tied]   # off the window edge if we can
            # among exact ties, the interval best placed to absorb one more break
            t = max(pool, key=lambda x: (cov[x] - taken[x] - req[x], -x.timestamp()))
            sh.break_start, sh.break_minutes = t, rule["minutes"]
            taken[t] += 1
        return taken

    def assign_breaks(self) -> None:
        for (day, q) in list(self.dq):
            self.breaks(day, q)

    def _group(self, day: date, q: str):
        """Cached (score, agents on break) for one day and queue; dropped when its shifts change."""
        hit = self._scores.get((day, q))
        if hit is None:
            taken = self.breaks(day, q)
            req, cov = self.required[q], self.cover[q]
            gaps = fails = depth = 0
            ops = self.op_set[q]
            for t in self.day_grid[day]:
                f = self.floors[q][t]
                if f and constraints.cover(cov[t], self.cross[q][t], self.cfg) < f:
                    gaps += 1
                if t in ops:
                    d = req[t] - (cov[t] - taken[t])
                    if d > 0:
                        fails += 1
                        depth += d
            hit = self._scores[(day, q)] = ((gaps, fails, depth), taken)
        return hit

    def group_score(self, day: date, q: str) -> tuple[int, int, int]:
        """(floor gaps, operating intervals short net of breaks, total shortage) for one day and queue."""
        return self._group(day, q)[0]

    def hours(self) -> float:
        return sum(_elapsed_hours(sh.segments) for sh in self.shifts)

    def shortfalls(self) -> list[tuple[str, date, datetime, int]]:
        """(queue, day, interval, shortage) for every operating interval short net of breaks."""
        out = []
        for day in self.days:
            for q in self.queues:
                taken = self._group(day, q)[1]
                for t in self.day_grid[day]:
                    d = self.required[q][t] - (self.cover[q][t] - taken[t])
                    if t in self.op_set[q] and d > 0:
                        out.append((q, day, t, d))
        return out


def required_hours(req: pd.DataFrame, cfg: dict) -> float:
    return float(req["required"].sum()) * cfg["interval_minutes"] / 60.0


def schedule_week(req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str) -> list[Shift]:
    plan = _Plan(req, cfg, agents, week)
    for day in plan.days:
        plan.fill_day(day)
    budget = float(cfg.get("efficiency_bound", 1e9)) * required_hours(req, cfg) - 0.05
    _improve(plan, budget)
    for q in plan.queues:            # a queue the roster cannot fully cover: search for the best it can get
        if _attainment(plan, q) < float(cfg.get("sla_target", 1.0)):
            _anneal(plan, q, budget, int(cfg.get("anneal_iterations", 30000)), f"{cfg['client']}-{week}-{q}")
            _improve(plan, budget)
    plan.assign_breaks()
    return plan.shifts


def _attainment(plan: _Plan, q: str) -> float:
    ops = plan.ops[q]
    fails = sum(plan.group_score(d, q)[1] for d in plan.days)
    return 1.0 - fails / len(ops) if ops else 1.0


def _energy(delta) -> float:
    return 10000 * delta[0] + 100 * delta[1] + delta[2]


def _anneal(plan: _Plan, q: str, budget: float, iterations: int, seed: str) -> None:
    """Simulated annealing over queue `q`'s shifts (re-template, drop, add, move, swap two agents' days),
    minimising (floor gaps, intervals short, shortage) with the rules enforced by `feasible`. Seeded from
    the run's own key, so a re-run gives the same schedule. The best plan seen is restored at the end."""
    rng = random.Random(seed)
    T0, T1 = float(plan.cfg.get("anneal_temperature", [60.0, 2.0])[0]), float(plan.cfg.get("anneal_temperature", [60.0, 2.0])[1])
    agents = [a for a in plan.agents if q in a.skills]
    tpls = plan.templates
    hours = plan.hours()

    def energy_now() -> float:
        return _energy(tuple(sum(plan.group_score(d, qq)[k] for d in plan.days for qq in plan.queues) for k in range(3)))

    cur = best = energy_now()
    best_state = [(sh.agent_id, sh.queue, sh.template, sh.day) for sh in plan.shifts]
    for i in range(iterations):
        temp = T0 * ((T1 / T0) ** (i / iterations))
        mine = [sh for sh in plan.shifts if sh.queue == q]
        kind = rng.random()
        removes: list[Shift] = []
        adds: list[tuple] = []
        if kind < 0.3 and mine:                       # re-template or drop
            sh = rng.choice(mine)
            removes = [sh]
            if rng.random() > 0.15:
                adds = [(plan.agent[sh.agent_id], q, rng.choice(tpls), sh.day)]
        elif kind < 0.55 and mine:                    # move to another day
            sh = rng.choice(mine)
            removes = [sh]
            adds = [(plan.agent[sh.agent_id], q, rng.choice(tpls) if rng.random() < 0.5 else sh.template,
                     rng.choice(plan.days))]
        elif kind < 0.75:                             # add
            adds = [(rng.choice(agents), q, rng.choice(tpls), rng.choice(plan.days))]
        elif len(mine) > 1:                           # swap two agents' shifts
            s1, s2 = rng.sample(mine, 2)
            a1, a2 = plan.agent[s1.agent_id], plan.agent[s2.agent_id]
            if a1 is a2:
                continue
            removes = [s1, s2]
            adds = [(a1, q, s2.template, s2.day), (a2, q, s1.template, s1.day)]
        else:
            continue
        d_hours = sum(_elapsed_hours(tpl.segments_utc(day, plan.tz)) for _, _, tpl, day in adds) \
            - sum(_elapsed_hours(sh.segments) for sh in removes)
        if hours + d_hours > budget:
            continue
        r = _try(plan, removes, adds)
        if r is None:
            continue
        delta, added = r
        dE = _energy(delta)
        if dE <= 0 or rng.random() < math.exp(-dE / temp):
            cur += dE
            hours += d_hours
            if cur < best - 1e-9:
                best = cur
                best_state = [(sh.agent_id, sh.queue, sh.template, sh.day) for sh in plan.shifts]
        else:
            _undo(plan, removes, added)
    for sh in list(plan.shifts):
        plan.remove(sh)
    for aid, qq, tpl, day in best_state:
        segs = tpl.segments_utc(day, plan.tz)
        plan.add(plan.agent[aid], qq, tpl, day, segs, _covered(segs, plan.day_grid[day]))


def _try(plan: _Plan, removes: list[Shift], adds: list[tuple]) -> tuple | None:
    """Apply removes then adds (agent, queue, template, day), if every add is feasible. Returns the score
    delta and the added shifts with the plan left changed; None (plan untouched) if infeasible."""
    groups = {(sh.day, sh.queue) for sh in removes} | {(d, q) for _, q, _, d in adds}
    before = [plan.group_score(d, q) for d, q in groups]
    for sh in removes:
        plan.remove(sh)
    added: list[Shift] = []
    for a, q, tpl, day in adds:
        segs = tpl.segments_utc(day, plan.tz)
        if not plan.feasible(a, tpl, day, segs):
            _undo(plan, removes, added)
            return None
        added.append(plan.add(a, q, tpl, day, segs, _covered(segs, plan.day_grid[day])))
    after = [plan.group_score(d, q) for d, q in groups]
    delta = tuple(sum(x[k] for x in after) - sum(x[k] for x in before) for k in range(3))
    return delta, added


def _undo(plan: _Plan, removes: list[Shift], added: list[Shift]) -> None:
    for sh in added:
        plan.remove(sh)
    for sh in removes:
        plan.insert(sh)


def _open_shortfalls(plan: _Plan, blocked) -> list[tuple[str, date, datetime, int]]:
    floors_short = [(q, day, t, 1) for (day, q) in plan.dq for t in plan.day_grid[day]
                    if plan.floors[q][t] and constraints.cover(plan.cover[q][t], plan.cross[q][t], plan.cfg) < plan.floors[q][t]]
    return sorted((x for x in floors_short + plan.shortfalls() if (x[0], x[2]) not in blocked),
                  key=lambda p: (-p[3], p[2], p[0]))


def _improve(plan: _Plan, budget: float) -> None:
    """Local search on the filled plan; score = (floor gaps, intervals short, shortage), lower is better.
    Add shifts where one helps; trim shifts that no longer matter; where no single added shift helps,
    re-template, re-queue or move an existing shift. Hours stay within `budget`."""
    while True:
        _add_phase(plan, budget)
        _trim(plan)
        if not _swap_phase(plan, budget):
            break
    _trim(plan)


def _best_move(plan: _Plan, q: str, day: date, t: datetime, budget: float, swaps: bool):
    hours = plan.hours()
    best = None
    for tpl in plan.templates:
        segs = tpl.segments_utc(day, plan.tz)
        if t not in _covered(segs, plan.day_grid[day]):
            continue
        cands = []
        if not swaps:
            a = plan.pick_agent(q, tpl, day, segs)
            if a is not None:
                cands.append(([], [(a, q, tpl, day)]))
        else:
            for sh in plan.shifts:   # an agent's shift that day (re-template/re-queue), or a q-shift from another day
                ag = plan.agent[sh.agent_id]
                if q not in ag.skills or (sh.day == day and sh.queue == q):
                    continue
                if sh.day == day or sh.queue == q:
                    cands.append(([sh], [(ag, q, tpl, day)]))
        for removes, adds in cands:
            cost = hours - sum(_elapsed_hours(s.segments) for s in removes) + _elapsed_hours(segs)
            if cost > budget + 1e-9:
                continue
            r = _try(plan, removes, adds)
            if r is None:
                continue
            delta, added = r
            _undo(plan, removes, added)
            key = (delta, cost, tpl.id, adds[0][0].agent_id, tuple(s.agent_id + str(s.day) for s in removes))
            if best is None or key < best[0]:
                best = (key, removes, adds)
    return best


def _add_phase(plan: _Plan, budget: float) -> None:
    blocked: set[tuple[str, datetime]] = set()
    while True:
        short = _open_shortfalls(plan, blocked)
        if not short:
            return
        q, day, t, _ = short[0]
        best = _best_move(plan, q, day, t, budget, swaps=False)
        if best is None or best[0][0] >= (0, 0, 0):
            blocked.add((q, t))
            continue
        _, removes, adds = best
        assert _try(plan, removes, adds) is not None
        blocked.clear()


def _swap_phase(plan: _Plan, budget: float) -> bool:
    """Apply one improving re-template / re-queue / relocate move, if any short interval has one."""
    for q, day, t, _ in _open_shortfalls(plan, set()):
        best = _best_move(plan, q, day, t, budget, swaps=True)
        if best is not None and best[0][0] < (0, 0, 0):
            _, removes, adds = best
            assert _try(plan, removes, adds) is not None
            return True
    return False


def _trim(plan: _Plan) -> None:
    """Drop or shorten shifts while no queue-day gets worse: fewer hours, same attainment."""
    changed = True
    while changed:
        changed = False
        for sh in sorted(plan.shifts, key=lambda s: (-_elapsed_hours(s.segments), s.day, s.agent_id)):
            if sh not in plan.shifts:
                continue
            ag = plan.agent[sh.agent_id]
            opts = [([sh], [])] + [([sh], [(ag, sh.queue, tpl, sh.day)]) for tpl in plan.templates
                                   if tpl.hours < sh.template.hours and not tpl.is_split]
            for removes, adds in opts:
                r = _try(plan, removes, adds)
                if r is None:
                    continue
                delta, added = r
                if all(x <= 0 for x in delta):
                    changed = True
                    break
                _undo(plan, removes, added)

