# independent Erlang C via direct factorial sums with Fractions-free floats
def pw(a,n):
    num=a**n/math.factorial(n)*n/(n-a)
    den=sum(a**k/math.factorial(k) for k in range(n))+num
    return num/den
def sl(a,n,aht,t): return 1-pw(a,n)*math.exp(-(n-a)*t/aht)
