"""Independent recomputation of Litware SOW checks from the raw export, roster and schedule.csv."""
import sys, math, json
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo
import pandas as pd
week, root = sys.argv[1], sys.argv[2]
Z = ZoneInfo("Europe/London")
ex = pd.read_csv(f"{root}/data/litware/export_{week}.csv")
ex["end"] = pd.to_datetime(ex.interval_end_local.str.cat(ex.utc_offset), format="%Y-%m-%d %H:%M%z", utc=True)
ex["start"] = ex.end - pd.Timedelta(minutes=20)
def pw(a, n):
    num = a**n/math.factorial(n)*n/(n-a); return num/(sum(a**k/math.factorial(k) for k in range(n))+num)
TG = {"priority": (0.9, 30), "standard": (0.8, 30), "email": (0.8, 300)}
def req(v, aht, q):
    a = v*aht/1200
    if a <= 0: return 0
    n = max(1, math.floor(a)+1)
    while True:
        s = 1-pw(a, n)*math.exp(-(n-a)*TG[q][1]/aht)
        if s >= TG[q][0] and a/n <= 0.85: return n
        n += 1
ex["req"] = [req(v, a, q) for v, a, q in zip(ex.volume, ex.aht_sec, ex.queue)]
agents = pd.read_csv(f"{root}/data/agents/litware.csv").set_index("agent_id")
sc = pd.read_csv(f"{root}/out/litware/schedule.csv", parse_dates=["segment_start_utc", "segment_end_utc", "break_start_utc"])
grid = sorted(ex.start.unique()); grid = [pd.Timestamp(t) for t in grid]
step = pd.Timedelta(minutes=20)
loc = lambda t: t.tz_convert(Z)
viol = []
# per segment
gross = {q: {t: 0 for t in grid} for q in TG}; brk = {q: {t: 0 for t in grid} for q in TG}
for r in sc.itertuples():
    a = agents.loc[r.agent_id]
    if r.queue not in a.skills.split(";"): viol.append(("skill", r.agent_id))
    if r.queue == "email" and loc(r.segment_start_utc).hour < 9: viol.append(("emailstart", r))
